using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;
using Framework.Tilemap;
using Framework.Movement;

namespace Game.Tests
{
    /// <summary>
    /// 汎用グリッド移動システムの動作確認用クラス。
    ///
    /// 固定マップを利用して移動、方向予約、壁判定、
    /// 停止、速度変更、イベントなどを検証する。
    /// </summary>
    public class GridMovementControllerTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("テスト対象")]

        /// <summary>
        /// テスト対象の移動コンポーネント。
        /// </summary>
        [SerializeField]
        private GridMovementController movement;

        /// <summary>
        /// グリッド座標変換システム。
        /// </summary>
        [SerializeField]
        private GridCoordinateConverter coordinateConverter;

        [Header("Tilemap設定")]

        /// <summary>
        /// 床の描画先。
        /// </summary>
        [SerializeField]
        private Tilemap floorTilemap;

        /// <summary>
        /// 壁の描画先。
        /// </summary>
        [SerializeField]
        private Tilemap wallTilemap;

        /// <summary>
        /// 床の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase floorTile;

        /// <summary>
        /// 壁の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase wallTile;

        [Header("テスト設定")]

        /// <summary>
        /// シーン開始時に自動テストを実行するか。
        /// </summary>
        [SerializeField]
        [Tooltip("開始時に全自動テストを実行する")]
        private bool runTestsOnStart = true;

        /// <summary>
        /// 手動テスト時の移動速度。
        /// </summary>
        [SerializeField]
        [Min(0.1f)]
        private float manualMoveSpeed = 3f;

        /// <summary>
        /// テストキャラクターのZ座標補正値。
        /// </summary>
        [SerializeField]
        private float characterZOffset = -0.2f;

        #endregion

        #region Constants

        /// <summary>
        /// テストマップの横幅。
        /// </summary>
        private const int MapWidth = 7;

        /// <summary>
        /// テストマップの縦幅。
        /// </summary>
        private const int MapHeight = 5;

        /// <summary>
        /// 床を表すマスデータ。
        /// </summary>
        private const int Floor = 0;

        /// <summary>
        /// 壁を表すマスデータ。
        /// </summary>
        private const int Wall = 1;

        /// <summary>
        /// テスト時の初期配置マス。
        /// </summary>
        private static readonly Vector2Int StartCell =
            new Vector2Int(1, 1);

        /// <summary>
        /// 自動テスト時の移動速度。
        /// </summary>
        private const float TestMoveSpeed = 4f;

        /// <summary>
        /// 座標比較時の許容誤差。
        /// </summary>
        private const float PositionTolerance = 0.001f;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// テスト用の固定マップ。
        /// </summary>
        private GridMap<int> map;

        /// <summary>
        /// テストマップの描画システム。
        /// </summary>
        private GridTilemapRenderer<int> mapRenderer;

        /// <summary>
        /// 成功したテスト項目数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目数。
        /// </summary>
        private int failedCount;

        /// <summary>
        /// テスト中に到達したマスの一覧。
        /// </summary>
        private readonly List<Vector2Int> reachedCells =
            new List<Vector2Int>();

        /// <summary>
        /// 移動開始イベントの発生回数。
        /// </summary>
        private int movementStartedCount;

        /// <summary>
        /// 移動停止イベントの発生回数。
        /// </summary>
        private int movementStoppedCount;

        /// <summary>
        /// 方向変更イベントの発生回数。
        /// </summary>
        private int directionChangedCount;

        /// <summary>
        /// 瞬間移動イベントの発生回数。
        /// </summary>
        private int teleportedCount;

        #endregion

        #region Unity Methods

        /// <summary>
        /// シーン開始時の初期化処理。
        /// </summary>
        private void Start()
        {
            if (!ValidateReferences())
            {
                return;
            }

            CreateTestMap();

            RenderTestMap();

            SubscribeEvents();

            ResetMovement();

            if (runTestsOnStart)
            {
                RunAllTests();
            }
            else
            {
                PrepareManualTest();
            }
        }

        /// <summary>
        /// オブジェクト破棄時の後処理。
        /// </summary>
        private void OnDestroy()
        {
            UnsubscribeEvents();

            if (mapRenderer != null)
            {
                mapRenderer.Dispose();
                mapRenderer = null;
            }
        }

        #endregion

        #region Map Methods

        /// <summary>
        /// 固定テストマップを生成する。
        /// </summary>
        private void CreateTestMap()
        {
            map = new GridMap<int>(
                MapWidth,
                MapHeight,
                position =>
                {
                    // 外周を壁にする。
                    if (position.x == 0 ||
                        position.y == 0 ||
                        position.x == MapWidth - 1 ||
                        position.y == MapHeight - 1)
                    {
                        return Wall;
                    }

                    // 中央行は交差点のみ通路にする。
                    if (position.y == 2 &&
                        position.x != 3)
                    {
                        return Wall;
                    }

                    return Floor;
                });
        }

        /// <summary>
        /// テストマップをTilemapへ描画する。
        /// </summary>
        private void RenderTestMap()
        {
            floorTilemap.ClearAllTiles();
            wallTilemap.ClearAllTiles();

            mapRenderer =
                new GridTilemapRenderer<int>(map);

            mapRenderer.AddLayer(
                floorTilemap,
                (position, cell) => floorTile);

            mapRenderer.AddLayer(
                wallTilemap,
                (position, cell) =>
                    cell == Wall ? wallTile : null);

            mapRenderer.RenderAll();
        }

        /// <summary>
        /// 指定されたマスへの移動可能判定。
        /// </summary>
        /// <param name="position">確認するマス</param>
        /// <returns>床の場合はtrue</returns>
        private bool IsWalkable(Vector2Int position)
        {
            return map != null &&
                   map.TryGetCell(position, out int cell) &&
                   cell == Floor;
        }

        #endregion

        #region Initialization Methods

        /// <summary>
        /// 移動システムとイベント集計を初期化する。
        /// </summary>
        private void ResetMovement()
        {
            movement.AutoUpdate = false;

            movement.MoveSpeed = TestMoveSpeed;

            movement.Initialize(
                coordinateConverter,
                IsWalkable,
                StartCell,
                characterZOffset);

            reachedCells.Clear();

            movementStartedCount = 0;
            movementStoppedCount = 0;
            directionChangedCount = 0;
            teleportedCount = 0;
        }

        /// <summary>
        /// 手動テスト用の状態に初期化する。
        /// </summary>
        private void PrepareManualTest()
        {
            ResetMovement();

            movement.MoveSpeed = manualMoveSpeed;

            movement.AutoUpdate = true;
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// 移動システムのイベントを購読する。
        /// </summary>
        private void SubscribeEvents()
        {
            movement.MovementStarted += OnMovementStarted;
            movement.CellReached += OnCellReached;
            movement.DirectionChanged += OnDirectionChanged;
            movement.MovementStopped += OnMovementStopped;
            movement.Teleported += OnTeleported;
        }

        /// <summary>
        /// 移動システムのイベント購読を解除する。
        /// </summary>
        private void UnsubscribeEvents()
        {
            if (movement == null)
            {
                return;
            }

            movement.MovementStarted -= OnMovementStarted;
            movement.CellReached -= OnCellReached;
            movement.DirectionChanged -= OnDirectionChanged;
            movement.MovementStopped -= OnMovementStopped;
            movement.Teleported -= OnTeleported;
        }

        /// <summary>
        /// 移動開始イベントを記録する。
        /// </summary>
        /// <param name="position">移動開始マス</param>
        private void OnMovementStarted(Vector2Int position)
        {
            movementStartedCount++;
        }

        /// <summary>
        /// 到達したマスを記録する。
        /// </summary>
        /// <param name="position">到達マス</param>
        private void OnCellReached(Vector2Int position)
        {
            reachedCells.Add(position);
        }

        /// <summary>
        /// 方向変更イベントを記録する。
        /// </summary>
        /// <param name="previous">変更前の方向</param>
        /// <param name="current">変更後の方向</param>
        private void OnDirectionChanged(
            Vector2Int previous,
            Vector2Int current)
        {
            directionChangedCount++;
        }

        /// <summary>
        /// 移動停止イベントを記録する。
        /// </summary>
        /// <param name="position">停止マス</param>
        private void OnMovementStopped(Vector2Int position)
        {
            movementStoppedCount++;
        }

        /// <summary>
        /// 瞬間移動イベントを記録する。
        /// </summary>
        /// <param name="previous">移動前のマス</param>
        /// <param name="current">移動後のマス</param>
        private void OnTeleported(
            Vector2Int previous,
            Vector2Int current)
        {
            teleportedCount++;
        }

        #endregion

        #region Automated Tests

        /// <summary>
        /// すべての自動テストを実行する。
        /// </summary>
        [ContextMenu("テスト/全自動テストを実行する")]
        public void RunAllTests()
        {
            if (!CanTest())
            {
                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                TestInitialization();
                TestBasicMovement();
                TestContinuousMovement();
                TestDirectionBuffer();
                TestWallCollision();
                TestReverseDirection();
                TestPause();
                TestStop();
                TestSpeedChange();
                TestTeleport();
                TestFrameIndependence();
                TestDynamicWall();
                TestPauseOnArrival();
            }
            finally
            {
                PrintTestResult();

                // テスト終了後は手動操作可能な状態へ戻す。
                PrepareManualTest();
            }
        }

        /// <summary>
        /// 初期化状態を検証する。
        /// </summary>
        private void TestInitialization()
        {
            ResetMovement();

            Check(
                movement.IsInitialized,
                "移動システムの初期化");

            Check(
                movement.CurrentCell == StartCell,
                "初期マス座標");

            Check(
                IsAtWorldPosition(StartCell),
                "初期ワールド座標");

            Check(
                !movement.IsMoving &&
                movement.IsAtCellCenter,
                "初期停止状態");

            Check(
                movement.CurrentDirection == Vector2Int.zero,
                "初期移動方向");

            Check(
                !movement.HasRequestedDirection,
                "初期予約方向");
        }

        /// <summary>
        /// 基本移動とイベントを検証する。
        /// </summary>
        private void TestBasicMovement()
        {
            ResetMovement();

            Check(
                movement.RequestDirection(Vector2Int.right),
                "右方向の移動予約");

            movement.Tick(0.125f);

            Check(
                movement.IsMoving &&
                movement.IsTraversing,
                "移動開始状態");

            Check(
                movement.CurrentCell == StartCell,
                "移動途中の現在マス維持");

            Check(
                movement.TargetCell == new Vector2Int(2, 1),
                "移動先マスの設定");

            Check(
                Mathf.Approximately(
                    movement.SegmentProgress, 0.5f),
                "マス間移動進捗率");

            Check(
                reachedCells.Count == 0,
                "移動途中の到達通知抑制");

            movement.Tick(0.125f);

            Check(
                movement.CurrentCell == new Vector2Int(2, 1),
                "次のマスへの到達");

            Check(
                IsAtWorldPosition(new Vector2Int(2, 1)),
                "マス中心への座標補正");

            Check(
                reachedCells.Count == 1 &&
                reachedCells[0] == new Vector2Int(2, 1),
                "マス到達イベント");

            Check(
                movementStartedCount == 1,
                "移動開始イベント");
        }

        /// <summary>
        /// 複数マスの連続移動を検証する。
        /// </summary>
        private void TestContinuousMovement()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.625f);

            Check(
                movement.CurrentCell == new Vector2Int(3, 1),
                "複数マスの連続移動");

            Check(
                movement.TargetCell == new Vector2Int(4, 1),
                "連続移動中の次のマス");

            Check(
                Mathf.Approximately(
                    movement.SegmentProgress, 0.5f),
                "余剰移動時間の引き継ぎ");

            Check(
                reachedCells.Count == 2,
                "複数マスの到達イベント数");

            Check(
                reachedCells.Count == 2 &&
                reachedCells[0] == new Vector2Int(2, 1) &&
                reachedCells[1] == new Vector2Int(3, 1),
                "マス到達イベントの順序");
        }

        /// <summary>
        /// 先行入力による方向予約を検証する。
        /// </summary>
        private void TestDirectionBuffer()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            movement.RequestDirection(Vector2Int.up);

            Check(
                movement.RequestedDirection == Vector2Int.up,
                "移動途中の方向予約");

            movement.Tick(0.125f);

            Check(
                movement.CurrentCell == new Vector2Int(2, 1) &&
                movement.CurrentDirection == Vector2Int.right,
                "曲がれないマスでの移動継続");

            Check(
                movement.RequestedDirection == Vector2Int.up,
                "未採用の予約方向維持");

            movement.Tick(0.25f);

            Check(
                movement.CurrentCell == new Vector2Int(3, 1),
                "交差点への到達");

            movement.Tick(0.125f);

            Check(
                movement.CurrentDirection == Vector2Int.up,
                "交差点での予約方向採用");

            Check(
                movement.TargetCell == new Vector2Int(3, 2),
                "方向転換後の移動先");

            Check(
                !movement.HasRequestedDirection,
                "採用済み予約方向の消去");

            Check(
                directionChangedCount == 2,
                "方向変更イベント");
        }

        /// <summary>
        /// 壁と範囲外への移動禁止を検証する。
        /// </summary>
        private void TestWallCollision()
        {
            ResetMovement();

            Check(
                !movement.CanMove(Vector2Int.left),
                "隣接する壁への移動禁止");

            Check(
                !movement.CanEnterCell(new Vector2Int(-1, 1)),
                "マップ範囲外への移動禁止");

            Check(
                !movement.RequestDirection(new Vector2Int(1, 1)),
                "斜め方向入力の拒否");

            Check(
                !movement.RequestDirection(Vector2Int.zero),
                "無方向入力の拒否");

            movement.RequestDirection(Vector2Int.left);

            movement.Tick(1f);

            Check(
                !movement.IsMoving &&
                movement.CurrentCell == StartCell,
                "壁方向入力時の停止維持");

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(2f);

            Check(
                movement.CurrentCell == new Vector2Int(5, 1),
                "壁手前のマスへの到達");

            Check(
                !movement.IsMoving &&
                movement.IsAtCellCenter,
                "壁手前での自動停止");

            Check(
                movementStoppedCount == 1,
                "移動停止イベント");
        }

        /// <summary>
        /// 逆方向入力による方向反転を検証する。
        /// </summary>
        private void TestReverseDirection()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            movement.RequestDirection(Vector2Int.left);

            movement.Tick(0.125f);

            Check(
                movement.CurrentCell == new Vector2Int(2, 1),
                "反転前のマス中心到達");

            movement.Tick(0.125f);

            Check(
                movement.CurrentDirection == Vector2Int.left,
                "マス中心での逆方向移動");

            Check(
                movement.TargetCell == StartCell,
                "逆方向移動先の設定");

            movement.Tick(0.125f);

            Check(
                movement.CurrentCell == StartCell,
                "逆方向移動の完了");
        }

        /// <summary>
        /// 一時停止と再開を検証する。
        /// </summary>
        private void TestPause()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            Vector3 previousPosition =
                movement.transform.position;

            float previousProgress =
                movement.SegmentProgress;

            movement.Pause();

            movement.Tick(1f);

            Check(
                movement.IsPaused,
                "一時停止状態");

            Check(
                Vector3.Distance(
                    previousPosition,
                    movement.transform.position)
                    < PositionTolerance,
                "一時停止中の座標維持");

            Check(
                Mathf.Approximately(
                    previousProgress,
                    movement.SegmentProgress),
                "一時停止中の移動進捗維持");

            movement.Resume();

            movement.Tick(0.125f);

            Check(
                !movement.IsPaused &&
                movement.CurrentCell == new Vector2Int(2, 1),
                "一時停止位置からの再開");
        }

        /// <summary>
        /// 停止予約と即時停止を検証する。
        /// </summary>
        private void TestStop()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            movement.RequestStop();

            movement.Tick(1f);

            Check(
                movement.CurrentCell == new Vector2Int(2, 1),
                "停止予約による次マス到達");

            Check(
                !movement.IsMoving,
                "停止予約による移動停止");

            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            movement.StopImmediately();

            Check(
                !movement.IsMoving &&
                movement.IsAtCellCenter,
                "即時停止");

            Check(
                IsAtWorldPosition(StartCell),
                "即時停止時の出発マス復帰");

            Check(
                !movement.HasRequestedDirection,
                "停止時の予約方向解除");
        }

        /// <summary>
        /// 移動途中の速度変更を検証する。
        /// </summary>
        private void TestSpeedChange()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.125f);

            movement.MoveSpeed = 8f;

            movement.Tick(0.0625f);

            Check(
                movement.CurrentCell == new Vector2Int(2, 1),
                "移動途中の速度変更");

            Check(
                Mathf.Approximately(movement.MoveSpeed, 8f),
                "変更後の移動速度");

            movement.MoveSpeed = 0f;

            Vector3 previousPosition =
                movement.transform.position;

            movement.Tick(1f);

            Check(
                Vector3.Distance(
                    previousPosition,
                    movement.transform.position)
                    < PositionTolerance,
                "移動速度0での位置維持");
        }

        /// <summary>
        /// 瞬間移動を検証する。
        /// </summary>
        private void TestTeleport()
        {
            ResetMovement();

            Vector2Int destination =
                new Vector2Int(3, 3);

            Check(
                movement.TryTeleport(destination),
                "通路への瞬間移動");

            Check(
                movement.CurrentCell == destination,
                "瞬間移動後のグリッド座標");

            Check(
                IsAtWorldPosition(destination),
                "瞬間移動後のワールド座標");

            Check(
                !movement.TryTeleport(Vector2Int.zero),
                "壁への瞬間移動禁止");

            Check(
                teleportedCount == 1,
                "瞬間移動イベント");

            Check(
                reachedCells.Count == 0,
                "瞬間移動時の到達イベント抑制");
        }

        /// <summary>
        /// 時間分割による移動結果の違いを検証する。
        /// </summary>
        private void TestFrameIndependence()
        {
            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            movement.Tick(0.625f);

            Vector3 expectedPosition =
                movement.transform.position;

            Vector2Int expectedCell =
                movement.CurrentCell;

            int expectedReachedCount =
                reachedCells.Count;

            ResetMovement();

            movement.RequestDirection(Vector2Int.right);

            for (int i = 0; i < 10; i++)
            {
                movement.Tick(0.0625f);
            }

            Check(
                Vector3.Distance(
                    expectedPosition,
                    movement.transform.position)
                    < PositionTolerance,
                "時間分割によるワールド座標の一致");

            Check(
                movement.CurrentCell == expectedCell,
                "時間分割によるグリッド座標の一致");

            Check(
                reachedCells.Count == expectedReachedCount,
                "時間分割による到達イベント数の一致");
        }

        /// <summary>
        /// 動的な壁変更への対応を検証する。
        /// </summary>
        private void TestDynamicWall()
        {
            ResetMovement();

            Vector2Int wallPosition =
                new Vector2Int(1, 2);

            try
            {
                Check(
                    !movement.CanMove(Vector2Int.up),
                    "変更前の壁判定");

                // 壁を床へ変更する。
                map.SetCell(wallPosition, Floor);

                Check(
                    movement.CanMove(Vector2Int.up),
                    "壁変更後の移動許可");

                movement.RequestDirection(Vector2Int.up);

                movement.Tick(0.25f);

                Check(
                    movement.CurrentCell == wallPosition,
                    "破壊された壁への移動");
            }
            finally
            {
                // テストマップを元の状態へ戻す。
                ResetMovement();

                map.SetCell(wallPosition, Wall);
            }
        }

        /// <summary>
        /// 到達イベント内からの一時停止を検証する。
        /// </summary>
        private void TestPauseOnArrival()
        {
            ResetMovement();

            movement.CellReached += PauseOnArrival;

            try
            {
                movement.RequestDirection(Vector2Int.right);

                movement.Tick(1f);

                Check(
                    movement.IsPaused,
                    "到達イベント内からの一時停止");

                Check(
                    movement.CurrentCell ==
                    new Vector2Int(2, 1),
                    "到達時停止による追加移動防止");

                Check(
                    reachedCells.Count == 1,
                    "到達時停止による追加通知防止");
            }
            finally
            {
                movement.CellReached -= PauseOnArrival;
            }
        }

        /// <summary>
        /// マス到達時に移動を一時停止する。
        /// </summary>
        /// <param name="position">到達したマス</param>
        private void PauseOnArrival(Vector2Int position)
        {
