        #region Utility Methods

        /// <summary>
        /// 指定マスの中心に配置されているか確認する。
        /// </summary>
        /// <param name="position">確認するマス</param>
        /// <returns>マス中心にいる場合はtrue</returns>
        private bool IsAtWorldPosition(Vector2Int position)
        {
            Vector3 expectedPosition =
                coordinateConverter.GetCellCenterWorld(
                    position);

            expectedPosition.z += characterZOffset;

            return Vector3.Distance(
                expectedPosition,
                movement.transform.position)
                < PositionTolerance;
        }

        /// <summary>
        /// 必要なInspector参照を確認する。
        /// </summary>
        /// <returns>参照が有効な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (movement == null ||
                coordinateConverter == null ||
                floorTilemap == null ||
                wallTilemap == null ||
                floorTile == null ||
                wallTile == null ||
                floorTilemap == wallTilemap)
            {
                Debug.LogError(
                    "テストに必要な参照を確認してください。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>
        /// テストを実行できる状態か確認する。
        /// </summary>
        /// <returns>実行可能な場合はtrue</returns>
        private bool CanTest()
        {
            if (!Application.isPlaying ||
                map == null ||
                movement == null ||
                !movement.IsInitialized)
            {
                Debug.LogWarning(
                    "再生モードで初期化後に実行してください。",
                    this);

                return false;
            }

            return true;
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// 自動テストの集計結果を出力する。
        /// </summary>
        private void PrintTestResult()
        {
            string message =
                "【GridMovementController テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべての実行済みテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

